// Maakt het jobbestand aan waar de rest van de workflow zijn voortgang in
// bijhoudt, en laat de binaries ongemoeid doorlopen naar Lees Upload.
const item = $input.first();

const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';
const nu = new Date();
const stempel =
  nu.getFullYear() +
  String(nu.getMonth() + 1).padStart(2, '0') +
  String(nu.getDate()).padStart(2, '0') +
  '_' +
  String(nu.getHours()).padStart(2, '0') +
  String(nu.getMinutes()).padStart(2, '0') +
  String(nu.getSeconds()).padStart(2, '0');
// Het jobId moet op het executienummer eindigen: daaraan vindt de workflow
// Foutafhandeling het jobbestand terug als deze run onderweg afbreekt.
const jobId = `ko_${stempel}_${String($execution.id || Math.random().toString(36).slice(2))}`
  .replace(/[^0-9A-Za-z_-]/g, '_');

fs.mkdirSync(JOB_DIR, { recursive: true });

// Oude jobbestanden opruimen; ze bevatten dossierinhoud en horen niet langer te
// blijven staan dan nodig is om het resultaat op te halen.
const BEWAARTERMIJN_MS = 24 * 60 * 60 * 1000;
try {
  for (const naam of fs.readdirSync(JOB_DIR)) {
    if (!naam.endsWith('.json')) continue;
    const pad = `${JOB_DIR}/${naam}`;
    if (Date.now() - fs.statSync(pad).mtimeMs > BEWAARTERMIJN_MS) fs.unlinkSync(pad);
  }
} catch (_) {
  // Best-effort: een nieuw dossier mag hier niet op stuklopen.
}

fs.writeFileSync(
  `${JOB_DIR}/${jobId}.json`,
  JSON.stringify({
    job_id: jobId,
    soort: 'koopovereenkomst',
    status: 'document omzetten',
    fase: 1,
    resultaat: null,
    fout: null,
    gestart_op: nu.toISOString(),
    bijgewerkt_op: nu.toISOString(),
  }),
  'utf8'
);

return [{ json: { ...(item.json || {}), jobId, stempel }, binary: item.binary }];

// Leest de multipart-upload en bouwt per document een Docling-item (base64).
// Meestal is dat één pdf; een losse lijst van zaken of een allonge mag erbij.
const item = $input.first();
const b = item.binary || {};
const body = (item.json && item.json.body) || {};

function isDocument(k) {
  const fn = String(b[k]?.fileName || '').toLowerCase();
  const mime = String(b[k]?.mimeType || '').toLowerCase();
  return fn.endsWith('.pdf') || fn.endsWith('.docx') || mime.includes('pdf') || mime.includes('wordprocessingml');
}

const sleutels = Object.keys(b).filter(isDocument).slice(0, 5);
if (sleutels.length === 0) {
  throw new Error('Geen koopovereenkomst ontvangen. Upload een pdf- of Word-bestand.');
}

const uit = [];
for (const k of sleutels) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, k);
  uit.push({
    json: {
      filename: b[k]?.fileName || `${k}.pdf`,
      base64_string: buffer.toString('base64'),
      dossiernummer: String(body.dossiernummer || '').trim().slice(0, 40),
      auteur: String(body.auteur || '').trim().slice(0, 80),
    },
  });
}
return uit;

// Per Docling-response: pak de markdown en bewaar de bestandsnaam.
const bron = $('Lees Upload').itemMatching($itemIndex);
const filename = bron?.json?.filename || '';

const payload = $json;
let md = '';
if (payload?.document?.md_content) md = payload.document.md_content;
else if (payload?.md_content) md = payload.md_content;
else if (payload?.result?.document?.md_content) md = payload.result.document.md_content;
else if (Array.isArray(payload?.documents) && payload.documents[0]?.md_content) md = payload.documents[0].md_content;

if (!md) {
  throw new Error(`Docling gaf geen tekst terug voor ${filename || 'het document'}. Is het een leesbare pdf?`);
}

// Docling sluit afbeeldingen (logo's, parafen, handtekeningen) als base64 in de
// markdown in. Die vullen het contextvenster van het model en moeten eruit
// voordat er iets wordt afgekapt of geselecteerd.
md = String(md)
  .replace(/!\[[^\]]*\]\(\s*data:[^)]*\)/gi, '')
  .replace(/<img[^>]*src=["']?data:[^>]*>/gi, '')
  .replace(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return { json: { filename, markdown: md } };

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

// Voegt de omgezette documenten samen en bouwt de eerste, smalle vraag aan het
// model: wie zijn de verkopers en de kopers. De partijen staan in elk
// koopmodel vooraan, dus alleen het begin van het document gaat mee.
const items = $input.all();
const markdown = items.map((it) => String(it.json.markdown || '')).join('\n\n').trim();
const bestanden = items.map((it) => it.json.filename).filter(Boolean);

// Geen koopovereenkomst: eerst de job op 'fout' zetten, pas daarna gooien.
// Andersom wacht de webapp op een antwoord dat nooit komt.
const laag = markdown.toLowerCase();
if (!/koop/.test(laag) || !/verkoper/.test(laag) || !/koper/.test(laag)) {
  const melding =
    'Dit document lijkt geen koopovereenkomst: de woorden koop, verkoper en koper komen er niet ' +
    'samen in voor. Is het een scan, controleer dan of de tekst leesbaar is.';
  werkJobBij({ status: 'fout', fase: 4, fout: melding });
  throw new Error(melding);
}

werkJobBij({ status: 'partijen uitlezen', fase: 2 });

// Tot en met de omschrijving van het verkochte; die staat vóór artikel 1.
const MAX_KOP = 9000;
const artikel1 = markdown.search(/\bartikel\s*1\b/i);
const kop = markdown.slice(0, artikel1 > 1500 ? Math.min(artikel1, MAX_KOP) : MAX_KOP);

// Geen ingevulde voorbeelden in de prompt: dit model schrijft die terug als
// inhoud. Het schema is daarom leeg en de uitleg staat in de regels.
const chatInput = `Je leest het begin van een Nederlandse koopovereenkomst voor een onroerende zaak. Haal de verkopers en de kopers eruit.

Geef ALLEEN geldige JSON terug, precies in deze vorm:
{"verkopers":[],"kopers":[]}

Elke persoon in die lijsten is een object met precies deze velden:
{"achternaam":"","voornamen":"","geboorteplaats":"","geboortedatum":"","straat_huisnummer":"","postcode":"","woonplaats":"","burgerlijke_staat":"","legitimatie":"","telefoon":"","email":""}

Regels:
- Neem gegevens letterlijk over uit het document. Verzin, vertaal of verbeter niets.
- Staat een gegeven er niet, laat het veld dan leeg.
- achternaam is inclusief tussenvoegsel. Bij een rechtspersoon komt de volledige naam in achternaam.
- legitimatie is de soort en het nummer van het identiteitsbewijs.
- Hooguit 4 verkopers en hooguit 4 kopers.
- Een makelaar, notaris of adviseur is geen partij.

DOCUMENT:
${kop}`;

return [{ json: { markdown, bestanden, chatInput } }];

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'object en afspraken uitlezen', fase: 3 });

// Tweede smalle vraag: het object en de afspraken. Een koopovereenkomst is al
// gauw 40.000 tekens en past niet in het contextvenster; het overgrote deel is
// standaardtekst. Past het document, dan gaat het heel mee. Anders alleen de
// stukken rond de woorden waar de ingevulde gegevens bij staan.
const markdown = String($('Build Partijen Prompt').first().json.markdown || '');

const MAX_HEEL = 14000;
const VENSTER_VOOR = 250;
const VENSTER_NA = 900;
const ANKERS = [
  /plaatselijk bekend/gi,
  /kadastraal bekend/gi,
  /koopsom van|koopprijs van|tegen een koopsom|koopsom bedraagt/gi,
  /roerende zaken/gi,
  /kosten koper|vrij op naam/gi,
  /akte van levering zal|gepasseerd worden|ten overstaan van/gi,
  /bankgarantie|waarborgsom/gi,
  /ontbindende voorwaarde/gi,
  /financiering van de onroerende zaak|hypothecaire geldlening/gi,
  /nationale hypotheek garantie|bouwkundige keuring|huisvestingsvergunning/gi,
  /erfpacht|canon/gi,
  /ouderdomsclausule|asbest|nadere afspraken|bijzondere bepalingen|aanvullende bepalingen/gi,
  /getekend te|ondertekend te|aldus overeengekomen/gi,
  /makelaar/gi,
];

function fragmenten(tekst) {
  const stukken = [];
  for (const rx of ANKERS) {
    let m;
    let aantal = 0;
    // Hooguit drie vindplaatsen per anker: 'koper' en 'notaris' staan in elke
    // alinea, maar de ingevulde gegevens staan bij de eerste paar.
    while ((m = rx.exec(tekst)) !== null && aantal < 3) {
      stukken.push([Math.max(0, m.index - VENSTER_VOOR), Math.min(tekst.length, m.index + VENSTER_NA)]);
      aantal++;
    }
  }
  stukken.sort((a, b) => a[0] - b[0]);
  const samen = [];
  for (const s of stukken) {
    const laatste = samen[samen.length - 1];
    if (laatste && s[0] <= laatste[1]) laatste[1] = Math.max(laatste[1], s[1]);
    else samen.push([...s]);
  }
  return samen.map(([a, b]) => tekst.slice(a, b).trim()).join('\n[…]\n');
}

let selectie = markdown;
let ingekort = false;
if (markdown.length > MAX_HEEL) {
  selectie = fragmenten(markdown).slice(0, MAX_HEEL);
  ingekort = true;
}

const chatInput = `Je leest ${ingekort ? 'fragmenten uit' : ''} een Nederlandse koopovereenkomst voor een onroerende zaak. Haal het verkochte object en de afspraken eruit.

Geef ALLEEN geldige JSON terug, precies in deze vorm:
{"object":{"straat_huisnummer":"","postcode":"","plaats":"","omschrijving":"","kadastrale_gemeente":"","sectie":"","perceelnummer":"","grootte":""},"koopsom":"","roerende_zaken_bedrag":"","kosten":"","datum_levering":"","notaris":"","zekerheid_bedrag":"","zekerheid_datum":"","financiering_bedrag":"","financiering_datum":"","overige_voorbehouden":[],"bijzonderheden":[],"makelaar":"","datum_ondertekening":""}

Regels:
- Neem gegevens letterlijk over uit het document. Verzin, vertaal of verbeter niets.
- Staat een gegeven er niet, of staat er "niet van toepassing", laat het veld dan leeg.
- object is het verkochte, niet het woonadres van een partij. omschrijving is de soort zaak, in hooguit tien woorden.
- Bedragen in cijfers zoals ze er staan. Datums zoals ze er staan.
- kosten is "kosten koper" of "vrij op naam".
- datum_levering is de datum waarop de akte van levering wordt gepasseerd. notaris is de notaris of het kantoor dat daarbij wordt genoemd.
- zekerheid_bedrag en zekerheid_datum horen bij de bankgarantie of waarborgsom.
- financiering_bedrag en financiering_datum horen bij de ontbindende voorwaarde voor de financiering.
- overige_voorbehouden: de andere ontbindende voorwaarden die zijn ingevuld, elk als {"omschrijving":"","datum":""}. Hooguit 5. De wettelijke bedenktijd hoort hier niet bij.
- bijzonderheden: afspraken die afwijken van de standaardtekst, elk in één korte zin. Hooguit 6. Zijn er geen, geef dan een lege lijst.

DOCUMENT:
${selectie}`;

return [{ json: { chatInput, ingekort } }];

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

// Maakt van de twee model-antwoorden één dossier en legt elk veld naast het
// document. Uitgangspunt: het model mag voorstellen, het document beslist.
//  - Kadastrale aanduiding en koopsom staan in elk koopmodel in een vaste
//    formulering; die leest de code zelf en gaan vóór het model.
//  - Elk ander veld moet in het document terug te vinden zijn. Lukt dat niet,
//    dan komt het pad in 'twijfel' en kleurt de webapp het veld.
//  - Bedragen die in cijfers én letters staan worden tegen elkaar gelegd.
const DOSSIER_MAP = '/data/shared/dossiers';
const bron = $('Build Partijen Prompt').first().json;
const upload = $('Lees Upload').first().json;
const maak = $('Create Job').first().json;
const markdown = String(bron.markdown || '');

// ---------- model-antwoorden lezen ----------
function leesAntwoord(j) {
  if (!j || typeof j !== 'object') return null;
  let ruw = j?.message?.content;
  if (typeof ruw !== 'string') return null;
  ruw = ruw.trim();
  const start = ruw.indexOf('{');
  const eind = ruw.lastIndexOf('}');
  if (start === -1 || eind <= start) return null;
  try {
    return JSON.parse(ruw.slice(start, eind + 1));
  } catch (_) {
    return null;
  }
}

const partijen = leesAntwoord($('Partijen LLM').first()?.json);
const transactie = leesAntwoord($('Transactie LLM').first()?.json);
const meldingen = [];
if (!partijen) {
  meldingen.push({
    ernst: 'kritiek',
    titel: 'Partijen niet uitgelezen',
    toelichting: 'Het model gaf geen bruikbaar antwoord op de vraag naar verkopers en kopers. Vul ze handmatig in.',
  });
}
if (!transactie) {
  meldingen.push({
    ernst: 'kritiek',
    titel: 'Object en afspraken niet uitgelezen',
    toelichting: 'Het model gaf geen bruikbaar antwoord op de vraag naar het object en de afspraken. Vul ze handmatig in.',
  });
}

// ---------- normaliseren ----------
function tekst(v, max = 300) {
  if (v == null || typeof v === 'object') return '';
  const t = String(v).replace(/\s+/g, ' ').trim();
  // "niet van toepassing" is in een koopmodel een ingevuld vakje, geen gegeven.
  if (/^(n\.?v\.?t\.?|niet van toepassing|onbekend|geen|-+)$/i.test(t)) return '';
  return t.slice(0, max);
}

const MAANDEN = ['januari', 'februari', 'maart', 'april', 'mei', 'juni', 'juli', 'augustus', 'september', 'oktober', 'november', 'december'];

/** Datum als 'JJJJ-MM-DD', of '' als er geen datum in staat. */
function isoDatum(v) {
  const t = String(v || '').toLowerCase();
  let m = t.match(/\b(\d{1,2})\s+([a-z]+)\s+(\d{4})\b/);
  if (m && MAANDEN.includes(m[2])) {
    return `${m[3]}-${String(MAANDEN.indexOf(m[2]) + 1).padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  }
  m = t.match(/\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})\b/);
  if (m && +m[2] >= 1 && +m[2] <= 12) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  m = t.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (m) return m[0];
  return '';
}

function datumVoluit(iso) {
  const [j, m, d] = iso.split('-');
  return `${+d} ${MAANDEN[+m - 1]} ${j}`;
}

/** Bedrag in hele centen, of null. */
function centen(v) {
  const m = String(v || '').match(/(\d{1,3}(?:[.\s]\d{3})+|\d+)(?:,(\d{2}))?/);
  if (!m) return null;
  const c = parseInt(m[1].replace(/[.\s]/g, ''), 10) * 100 + (m[2] ? parseInt(m[2], 10) : 0);
  return Number.isFinite(c) && c > 0 ? c : null;
}

function bedragVoluit(c) {
  const euro = Math.floor(c / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return `€ ${euro},${String(c % 100).padStart(2, '0')}`;
}

function plat(s) {
  return String(s || '')
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase();
}

// ---------- wat staat er in het document ----------
const platDoc = plat(markdown);
const docWoorden = new Set(platDoc.match(/[a-z0-9@]+/g) || []);
// Telefoonnummers en postcodes staan nu eens met en dan zonder spatie of streep.
const docAaneen = platDoc.replace(/[^a-z0-9]/g, '');

const docBedragen = new Set();
for (const m of markdown.matchAll(/(?:€|EUR|euro)\s*((?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{2})?)/gi)) {
  const c = centen(m[1]);
  if (c) docBedragen.add(c);
}
const docDatums = new Set();
for (const m of markdown.matchAll(/\b\d{1,2}\s+[a-zA-Z]+\s+\d{4}\b|\b\d{1,2}[-/.]\d{1,2}[-/.]\d{4}\b/g)) {
  const iso = isoDatum(m[0]);
  if (iso) docDatums.add(iso);
}

/** Staat elke betekenisvolle lettergroep van de waarde in het document? */
function staatErin(waarde) {
  const woorden = plat(waarde).match(/[a-z0-9@]+/g) || [];
  if (woorden.length === 0) return true;
  if (woorden.every((w) => docWoorden.has(w))) return true;
  return docAaneen.includes(plat(waarde).replace(/[^a-z0-9]/g, ''));
}

const twijfel = [];

/** Vrij tekstveld: overnemen en markeren als het niet in het document staat. */
function veld(pad, v, max) {
  const t = tekst(v, max);
  if (t && !staatErin(t)) twijfel.push(pad);
  return t;
}

function datumVeld(pad, v) {
  const t = tekst(v);
  if (!t) return '';
  const iso = isoDatum(t);
  if (!iso) {
    twijfel.push(pad);
    return t;
  }
  if (!docDatums.has(iso)) twijfel.push(pad);
  return datumVoluit(iso);
}

function bedragVeld(pad, v) {
  const t = tekst(v);
  if (!t) return '';
  const c = centen(t);
  if (c == null) {
    twijfel.push(pad);
    return t;
  }
  if (!docBedragen.has(c)) twijfel.push(pad);
  return bedragVoluit(c);
}

// ---------- partijen ----------
function personen(lijst, rol) {
  if (!Array.isArray(lijst)) return [];
  return lijst
    .filter((p) => p && typeof p === 'object')
    .slice(0, 4)
    .map((p, i) => {
      const pad = (v) => `${rol}.${i}.${v}`;
      const persoon = {
        achternaam: veld(pad('achternaam'), p.achternaam),
        voornamen: veld(pad('voornamen'), p.voornamen),
        geboorteplaats: veld(pad('geboorteplaats'), p.geboorteplaats),
        geboortedatum: datumVeld(pad('geboortedatum'), p.geboortedatum),
        straat_huisnummer: veld(pad('straat_huisnummer'), p.straat_huisnummer),
        postcode: veld(pad('postcode'), p.postcode),
        woonplaats: veld(pad('woonplaats'), p.woonplaats),
        burgerlijke_staat: veld(pad('burgerlijke_staat'), p.burgerlijke_staat),
        legitimatie: veld(pad('legitimatie'), p.legitimatie),
        telefoon: veld(pad('telefoon'), p.telefoon),
        email: veld(pad('email'), p.email),
      };
      // Het koopmodel zet de postcode vaak vóór de woonplaats in één vakje.
      const pc = persoon.woonplaats.match(/^(\d{4}\s?[A-Za-z]{2})\s+(.+)$/);
      if (pc && !persoon.postcode) {
        persoon.postcode = pc[1].toUpperCase();
        persoon.woonplaats = pc[2];
      }
      return persoon;
    })
    .filter((p) => p.achternaam || p.voornamen);
}

const verkopers = personen(partijen?.verkopers, 'verkopers');
const kopers = personen(partijen?.kopers, 'kopers');
// 'twijfel' kan paden bevatten van personen die net zijn weggefilterd; die
// wijzen dan naar de verkeerde persoon. Lege personen komen alleen achteraan
// voor, dus alles voorbij de lengte kan weg.
function binnenBereik(pad) {
  const m = pad.match(/^(verkopers|kopers)\.(\d+)\./);
  if (!m) return true;
  return +m[2] < (m[1] === 'verkopers' ? verkopers : kopers).length;
}

// ---------- object ----------
const o = (transactie && typeof transactie.object === 'object' && transactie.object) || {};
const object = {
  straat_huisnummer: veld('object.straat_huisnummer', o.straat_huisnummer),
  postcode: veld('object.postcode', o.postcode),
  plaats: veld('object.plaats', o.plaats),
  omschrijving: veld('object.omschrijving', o.omschrijving),
  kadastrale_gemeente: veld('object.kadastrale_gemeente', o.kadastrale_gemeente),
  sectie: veld('object.sectie', o.sectie),
  perceelnummer: veld('object.perceelnummer', o.perceelnummer),
  grootte: veld('object.grootte', o.grootte),
};

// De kadastrale aanduiding heeft een vaste vorm; staat die er, dan gaat het
// document vóór het model. Bij meer percelen blijft alleen het eerste staan en
// volgt een melding.
const KAD_RX = /kadastraal bekend(?:\s+als)?:?\s+gemeente\s+([^,;\n]+?),?\s+sectie\s+([A-Z]{1,2}),?\s+(?:nummers?|nrs?\.?)\s+(\d+)/gi;
const percelen = [...markdown.matchAll(KAD_RX)];
if (percelen.length > 0) {
  const [, gemeente, sectie, nummer] = percelen[0];
  object.kadastrale_gemeente = gemeente.trim();
  object.sectie = sectie.toUpperCase();
  object.perceelnummer = nummer;
  for (const k of ['kadastrale_gemeente', 'sectie', 'perceelnummer']) {
    const i = twijfel.indexOf(`object.${k}`);
    if (i !== -1) twijfel.splice(i, 1);
  }
  const aantal = new Set(percelen.map((p) => `${p[2].toUpperCase()}${p[3]}`)).size;
  if (aantal > 1) {
    meldingen.push({
      ernst: 'let op',
      titel: `${aantal} kadastrale percelen in het document`,
      toelichting: 'Alleen het eerste perceel is overgenomen. Vul de overige aan bij Bijzonderheden of in de omschrijving.',
    });
  }
}

// ---------- afspraken ----------
const t = transactie || {};
const afspraken = {
  koopsom: bedragVeld('transactie.koopsom', t.koopsom),
  roerende_zaken_bedrag: bedragVeld('transactie.roerende_zaken_bedrag', t.roerende_zaken_bedrag),
  kosten: /vrij op naam|v\.?o\.?n/i.test(String(t.kosten || ''))
    ? 'vrij op naam'
    : /kosten koper|k\.?k/i.test(String(t.kosten || ''))
      ? 'kosten koper'
      : '',
  datum_levering: datumVeld('transactie.datum_levering', t.datum_levering),
  notaris: veld('transactie.notaris', t.notaris),
  zekerheid_bedrag: bedragVeld('transactie.zekerheid_bedrag', t.zekerheid_bedrag),
  zekerheid_datum: datumVeld('transactie.zekerheid_datum', t.zekerheid_datum),
  financiering_bedrag: bedragVeld('transactie.financiering_bedrag', t.financiering_bedrag),
  financiering_datum: datumVeld('transactie.financiering_datum', t.financiering_datum),
  makelaar: veld('transactie.makelaar', t.makelaar),
  datum_ondertekening: datumVeld('transactie.datum_ondertekening', t.datum_ondertekening),
  overige_voorbehouden: [],
  bijzonderheden: [],
};

// De koopsom staat in het model achter 'koopsom van'; staat die er, dan gaat
// het document vóór het model.
const koopsomDoc = markdown.match(/koop(?:som|prijs)\s+(?:van|bedraagt|is)?:?\s*(?:€|EUR)\s*((?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{2})?)/i);
if (koopsomDoc) {
  const c = centen(koopsomDoc[1]);
  if (c) {
    const uitDoc = bedragVoluit(c);
    if (afspraken.koopsom && afspraken.koopsom !== uitDoc) {
      meldingen.push({
        ernst: 'let op',
        titel: 'Koopsom gecorrigeerd aan de hand van het document',
        toelichting: `Het model las ${afspraken.koopsom}; achter 'koopsom' staat in het document ${uitDoc}. Het laatste is overgenomen.`,
      });
    }
    afspraken.koopsom = uitDoc;
    const i = twijfel.indexOf('transactie.koopsom');
    if (i !== -1) twijfel.splice(i, 1);
  }
}

// Lijsten: een punt dat niet in het document staat is geen twijfelgeval maar
// vrijwel zeker een echo van de prompt. Die laten we weg in plaats van hem te
// markeren. Voor een zin geldt: het merendeel van de inhoudswoorden moet er
// staan, want het model vat samen en gebruikt dus ook eigen woorden.
function gedekt(zin, drempel) {
  const woorden = (plat(zin).match(/[a-z0-9]+/g) || []).filter((w) => w.length > 3);
  if (woorden.length === 0) return false;
  return woorden.filter((w) => docWoorden.has(w)).length / woorden.length >= drempel;
}

if (Array.isArray(t.overige_voorbehouden)) {
  for (const v of t.overige_voorbehouden.slice(0, 5)) {
    if (!v || typeof v !== 'object') continue;
    const omschrijving = tekst(v.omschrijving, 240);
    const iso = isoDatum(v.datum);
    if (!omschrijving || !gedekt(omschrijving, 0.6)) continue;
    // Een voorbehoud zonder datum die in het document staat is niet ingevuld.
    if (!iso || !docDatums.has(iso)) continue;
    // De financiering heeft een eigen veld; hier alleen de overige.
    if (/financiering|hypothecaire geldlening/i.test(omschrijving) && datumVoluit(iso) === afspraken.financiering_datum) continue;
    afspraken.overige_voorbehouden.push({ omschrijving, datum: datumVoluit(iso) });
  }
}
if (Array.isArray(t.bijzonderheden)) {
  for (const b of t.bijzonderheden.slice(0, 6)) {
    const zin = tekst(b, 300);
    // Een voorbehoud hoort in de lijst hierboven, waar een datum uit het
    // document voor nodig is. Zonder die eis maakte het model van een
    // doorgehaalde NHG-bepaling een voorbehoud.
    if (/ontbind|ontbonden|voorbehoud/i.test(zin)) continue;
    if (zin && gedekt(zin, 0.6)) afspraken.bijzonderheden.push(zin);
  }
}

// ---------- cijfers tegen letters ----------
const EENHEDEN = ['nul', 'een', 'twee', 'drie', 'vier', 'vijf', 'zes', 'zeven', 'acht', 'negen', 'tien', 'elf', 'twaalf', 'dertien', 'veertien', 'vijftien', 'zestien', 'zeventien', 'achttien', 'negentien'];
const TIENTALLEN = ['', '', 'twintig', 'dertig', 'veertig', 'vijftig', 'zestig', 'zeventig', 'tachtig', 'negentig'];
function onder100(n) {
  if (n < 20) return EENHEDEN[n];
  const e = n % 10;
  return e ? `${EENHEDEN[e]}en${TIENTALLEN[Math.floor(n / 10)]}` : TIENTALLEN[n / 10];
}
function onder1000(n) {
  if (n < 100) return onder100(n);
  const h = Math.floor(n / 100);
  const rest = n % 100;
  return `${h === 1 ? '' : EENHEDEN[h]}honderd${rest ? onder100(rest) : ''}`;
}
function inWoorden(n) {
  if (!Number.isInteger(n) || n < 0 || n > 999999999) return null;
  if (n < 1000) return onder1000(n);
  if (n < 1000000) {
    const d = Math.floor(n / 1000);
    const rest = n % 1000;
    return `${d === 1 ? '' : onder1000(d)}duizend${rest ? onder1000(rest) : ''}`;
  }
  const m = Math.floor(n / 1000000);
  const rest = n % 1000000;
  return `${onder1000(m)}miljoen${rest ? inWoorden(rest) : ''}`;
}
// Spaties, trema's en streepjes wegen niet mee: 'zevenduizend vijfhonderd' en
// 'zevenduizendvijfhonderd' zijn hetzelfde bedrag.
function kaal(woorden) {
  return plat(woorden).replace(/[^a-z]/g, '');
}

for (const m of markdown.matchAll(/(?:€|EUR)\s*((?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d{2})?)\s*\(?\s*(?:zegge|in letters):?\s*([^)\n]{3,160})\)?/gi)) {
  const c = centen(m[1]);
  // Alleen hele euro's: centen in letters kennen te veel schrijfwijzen.
  if (!c || c % 100 !== 0) continue;
  const verwacht = inWoorden(c / 100);
  const staat = kaal(m[2].replace(/\beuro'?s?\b.*$/i, ''));
  if (verwacht && staat && kaal(verwacht) !== staat) {
    meldingen.push({
      ernst: 'kritiek',
      titel: 'Bedrag in cijfers en in letters verschilt',
      toelichting: `In het document staat ${bedragVoluit(c)}, maar in letters "${m[2].trim()}". Vraag na welk bedrag is bedoeld.`,
    });
  }
}

// ---------- dossier wegschrijven ----------
const nu = new Date().toISOString();
const id = `d_${maak.stempel}_${String($execution.id || Date.now()).replace(/[^0-9A-Za-z]/g, '')}`;
const dossier = {
  id,
  dossiernummer: upload.dossiernummer || '',
  soort: 'levering',
  status: 'concept',
  verkopers,
  kopers,
  object,
  transactie: afspraken,
  notitie: '',
  twijfel: [...new Set(twijfel)].filter(binnenBereik),
  meldingen,
  bron: { bestanden: bron.bestanden || [], tekens: markdown.length, uitgelezen_op: nu },
  historie: [{ op: nu, door: upload.auteur || '', actie: 'uitgelezen uit koopovereenkomst' }],
  aangemaakt_op: nu,
  bijgewerkt_op: nu,
};

// Eerst naar een tijdelijk bestand en dan hernoemen: een afgebroken schrijfactie
// laat zo nooit een half JSON-bestand achter.
fs.mkdirSync(DOSSIER_MAP, { recursive: true });
const pad = `${DOSSIER_MAP}/${id}.json`;
const tmp = `${pad}.${Date.now()}.tmp`;
fs.writeFileSync(tmp, JSON.stringify(dossier, null, 2) + '\n');
fs.renameSync(tmp, pad);

werkJobBij({ status: 'klaar', fase: 4, resultaat: { success: true, dossier } });

return [{ json: { dossier_id: id } }];

// GET /webhook/dossiers        -> overzicht, nieuwste eerst
// GET /webhook/dossiers?id=... -> één volledig dossier
const fs = require('fs');
const MAP = '/data/shared/dossiers';

// Alleen een ontbrekend bestand telt als 'bestaat niet'. Elke andere leesfout
// (EIO als macOS het bestand naar iCloud heeft weggeschreven) gooien we door:
// anders zou een volgende opslag een bestaand dossier leeg overschrijven.
function lees(id) {
  try {
    return JSON.parse(fs.readFileSync(`${MAP}/${id}.json`, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw new Error(`Kon dossier ${id} niet lezen: ${err.message}`);
  }
}

// We serialiseren zelf en laten de Respond-node de tekst onaangeroerd
// doorgeven; met respondWith=json komen regeleinden uit vrije tekst ongeëscaped
// in het antwoord terecht.
function antwoord(payload) {
  return [{ json: { payload: JSON.stringify(payload) } }];
}

// Een id komt uit Bouw Dossier en bestaat alleen uit deze tekens; zo kan een
// geknutselde parameter niet uit de dossiermap wegwandelen.
function schoonId(v) {
  const id = String(v || '');
  return /^d_[0-9A-Za-z_]{6,60}$/.test(id) ? id : '';
}

function naam(p) {
  return [p.voornamen, p.achternaam].filter(Boolean).join(' ');
}

// Verwachte fouten als {success:false} teruggeven: een throw levert bij
// responseMode=responseNode een leeg 200-antwoord op.
try {
  const query = $json.query || {};
  if (query.id !== undefined) {
    const id = schoonId(query.id);
    const dossier = id ? lees(id) : null;
    if (!dossier) return antwoord({ success: false, error: 'Dit dossier bestaat niet (meer).' });
    return antwoord({ success: true, dossier });
  }

  let bestanden = [];
  try {
    bestanden = fs.readdirSync(MAP).filter((n) => /^d_[0-9A-Za-z_]+\.json$/.test(n));
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }

  const dossiers = [];
  const onleesbaar = [];
  for (const bestand of bestanden) {
    try {
      const d = lees(bestand.replace(/\.json$/, ''));
      if (!d) continue;
      dossiers.push({
        id: d.id,
        dossiernummer: d.dossiernummer || '',
        soort: d.soort || '',
        status: d.status || 'concept',
        adres: [d.object?.straat_huisnummer, d.object?.plaats].filter(Boolean).join(', '),
        verkopers: (d.verkopers || []).map(naam).filter(Boolean),
        kopers: (d.kopers || []).map(naam).filter(Boolean),
        datum_levering: d.transactie?.datum_levering || '',
        open_punten: (d.twijfel || []).length,
        bijgewerkt_op: d.bijgewerkt_op || d.aangemaakt_op || '',
      });
    } catch (_) {
      // Eén onleesbaar dossier mag het overzicht niet leeg maken.
      onleesbaar.push(bestand);
    }
  }
  dossiers.sort((a, b) => String(b.bijgewerkt_op).localeCompare(String(a.bijgewerkt_op)));
  return antwoord({ success: true, dossiers, onleesbaar });
} catch (err) {
  return antwoord({ success: false, error: err.message });
}

// POST /webhook/dossier-opslaan
// Invoer (form-urlencoded veld 'data', JSON):
//   { actie: 'opslaan' | 'bevestigen' | 'heropenen' | 'verwijderen',
//     id, auteur, basis, dossier }
// 'basis' is de bijgewerkt_op die de webapp heeft geladen; wijkt die af van wat
// er op schijf staat, dan heeft een collega het dossier intussen gewijzigd.
const fs = require('fs');
const MAP = '/data/shared/dossiers';

// Alleen een ontbrekend bestand telt als 'bestaat niet'. Elke andere leesfout
// (EIO als macOS het bestand naar iCloud heeft weggeschreven) gooien we door:
// anders zou een volgende opslag een bestaand dossier leeg overschrijven.
function lees(id) {
  try {
    return JSON.parse(fs.readFileSync(`${MAP}/${id}.json`, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw new Error(`Kon dossier ${id} niet lezen: ${err.message}`);
  }
}

// We serialiseren zelf en laten de Respond-node de tekst onaangeroerd
// doorgeven; met respondWith=json komen regeleinden uit vrije tekst ongeëscaped
// in het antwoord terecht.
function antwoord(payload) {
  return [{ json: { payload: JSON.stringify(payload) } }];
}

// Een id komt uit Bouw Dossier en bestaat alleen uit deze tekens; zo kan een
// geknutselde parameter niet uit de dossiermap wegwandelen.
function schoonId(v) {
  const id = String(v || '');
  return /^d_[0-9A-Za-z_]{6,60}$/.test(id) ? id : '';
}

function tekst(v, max) {
  if (v == null || typeof v === 'object') return '';
  return String(v).replace(/\r\n/g, '\n').trim().slice(0, max);
}

const PERSOON = ['achternaam', 'voornamen', 'geboorteplaats', 'geboortedatum', 'straat_huisnummer', 'postcode', 'woonplaats', 'burgerlijke_staat', 'legitimatie', 'telefoon', 'email'];
const OBJECT = ['straat_huisnummer', 'postcode', 'plaats', 'omschrijving', 'kadastrale_gemeente', 'sectie', 'perceelnummer', 'grootte'];
const AFSPRAAK = ['koopsom', 'roerende_zaken_bedrag', 'kosten', 'datum_levering', 'notaris', 'zekerheid_bedrag', 'zekerheid_datum', 'financiering_bedrag', 'financiering_datum', 'makelaar', 'datum_ondertekening'];

// Alleen bekende velden overnemen: wat de webapp meestuurt gaat rechtstreeks
// naar schijf, dus een onbekende sleutel hoort daar niet te belanden.
function velden(bron, namen, max = 300) {
  const uit = {};
  for (const n of namen) uit[n] = tekst(bron && bron[n], max);
  return uit;
}

function personen(lijst) {
  if (!Array.isArray(lijst)) return [];
  return lijst.slice(0, 8).map((p) => velden(p, PERSOON));
}

let inv;
try {
  const body = $json.body || {};
  inv = typeof body.data === 'string' ? JSON.parse(body.data) : body.data || body;
} catch (err) {
  return antwoord({ success: false, error: 'Ongeldige invoer: ' + err.message });
}

try {
  const id = schoonId(inv.id);
  const bestaand = id ? lees(id) : null;
  if (!bestaand) return antwoord({ success: false, error: 'Dit dossier bestaat niet (meer).' });

  if (inv.basis && bestaand.bijgewerkt_op && inv.basis !== bestaand.bijgewerkt_op) {
    return antwoord({
      success: false,
      error: 'Dit dossier is intussen door iemand anders gewijzigd. Laad het opnieuw voordat je opslaat.',
    });
  }

  const actie = String(inv.actie || 'opslaan');
  const nu = new Date().toISOString();
  const auteur = tekst(inv.auteur, 80);
  const pad = `${MAP}/${id}.json`;

  if (actie === 'verwijderen') {
    // Niet weggooien maar opzijzetten: een dossier bevat handmatig nagekeken
    // gegevens en een misklik moet terug te draaien zijn.
    fs.mkdirSync(`${MAP}/.verwijderd`, { recursive: true });
    fs.renameSync(pad, `${MAP}/.verwijderd/${id}_${Date.now()}.json`);
    return antwoord({ success: true, verwijderd: id });
  }
  if (!['opslaan', 'bevestigen', 'heropenen'].includes(actie)) {
    return antwoord({ success: false, error: `Onbekende actie: ${actie}` });
  }

  const d = inv.dossier || {};
  const t = d.transactie || {};
  const nieuw = {
    ...bestaand,
    dossiernummer: tekst(d.dossiernummer, 40),
    verkopers: personen(d.verkopers),
    kopers: personen(d.kopers),
    object: velden(d.object, OBJECT),
    transactie: {
      ...velden(t, AFSPRAAK),
      overige_voorbehouden: (Array.isArray(t.overige_voorbehouden) ? t.overige_voorbehouden : [])
        .slice(0, 12)
        .map((v) => ({ omschrijving: tekst(v && v.omschrijving, 300), datum: tekst(v && v.datum, 40) }))
        .filter((v) => v.omschrijving || v.datum),
      bijzonderheden: (Array.isArray(t.bijzonderheden) ? t.bijzonderheden : [])
        .slice(0, 20)
        .map((b) => tekst(b, 400))
        .filter(Boolean),
    },
    notitie: tekst(d.notitie, 4000),
    twijfel: (Array.isArray(d.twijfel) ? d.twijfel : []).map((p) => tekst(p, 80)).filter(Boolean).slice(0, 200),
    bijgewerkt_op: nu,
  };
  if (actie === 'bevestigen') nieuw.status = 'bevestigd';
  if (actie === 'heropenen') nieuw.status = 'concept';

  const omschrijving = { opslaan: 'gewijzigd', bevestigen: 'gecontroleerd en bevestigd', heropenen: 'heropend' }[actie];
  nieuw.historie = [...(bestaand.historie || []), { op: nu, door: auteur, actie: omschrijving }].slice(-100);

  // Eerst naar een tijdelijk bestand en dan hernoemen: een afgebroken
  // schrijfactie laat zo nooit een half JSON-bestand achter.
  const tmp = `${pad}.${Date.now()}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(nieuw, null, 2) + '\n');
  fs.renameSync(tmp, pad);
  return antwoord({ success: true, dossier: nieuw });
} catch (err) {
  return antwoord({ success: false, error: err.message });
}
